// Some portions generated by Claude
import { useCallback, useEffect, useMemo, useRef, useState, useSyncExternalStore } from "react";
import { dataRevisionKey, readDataRevision, watchDataRevision } from "./data-revision.ts";
import type { SparqlResponse } from "./explorer-types.ts";
import { exactMatchQueries, type ExactMatch } from "./facet-queries.ts";
import {
  facetNamespace,
  facetPersistence,
  indexedDbFacetBackend,
  LABELS,
  memoryFacetBackend,
} from "./facet-store-persistence.ts";
import { FacetValueLabels, type StoredLabel } from "./facet-value-labels.ts";
import { isSparqlTerm, sparqlNodeId } from "./rdf-terms.ts";
import { RepositoryFacetStore } from "./repository-facets.ts";
import { repositoryScope } from "./repository-identity.ts";
import type { GraphScope } from "./rdf-vocabulary.ts";

/** How long the graph has to stay still before its new nodes are asked for. */
const SETTLE_MS = 500;
/** How often the panel hears about new values while they arrive. */
const PUBLISH_MS = 250;
const CONFIRM_BATCH = 200;

export type RepositoryFacets = ReturnType<typeof useRepositoryFacets>;

function inferenceOn() {
  if (typeof document === "undefined") return true;
  return !/(?:^|;\s*)infer=false(?:;|$)/.test(document.cookie);
}

function hasIndexedDb() {
  return typeof indexedDB !== "undefined";
}

/**
 * The Filters panel's values from the repository for the nodes the graph draws (repository-facets.ts), and labels for
 * the IRIs among them (facet-value-labels.ts). One store per repository, graph scope, inference setting and data
 * revision: a write through the Workbench, here or in another tab, starts a new one. Loading starts once the graph has
 * stayed still for half a second, focused nodes first, and runs in the background after the explorer's own queries.
 * `predicates` lists the predicates loaded so far, for the explorer to learn label predicates from; the labels are asked
 * for with the explorer's (`lookupProperties`), and a new list of them starts new labels.
 */
export function useRepositoryFacets(input: {
  basePath: string;
  repositoryId: string;
  serverIdentity: string;
  endpoint: string;
  /** Sends a query without counting it as the explorer's own (foreground) query. */
  execute: (endpoint: string, query: string, signal?: AbortSignal) => Promise<SparqlResponse>;
  scope: GraphScope;
  maxRows?: number;
  maxQueryLength?: number;
  languages: string[];
  /** The preferred label predicates, in order, and every label predicate the canvas asks with (RdfExplorer). */
  labelProperties: readonly string[];
  lookupProperties: readonly string[];
  /** The queryable nodes the Filters panel filters, and those to load first (selected, focused). */
  nodeIds: readonly string[];
  focusIds: readonly string[];
  /** Predicates to probe a hub for: those of the loaded links. */
  candidates: () => Iterable<string>;
  knownLabel: (iri: string) => string | undefined;
  foreground: { idle(): Promise<void> };
}) {
  const { basePath, repositoryId, serverIdentity, endpoint, execute, scope } = input;
  const revisionKey = useMemo(
    () => dataRevisionKey(basePath, repositoryId, serverIdentity),
    [basePath, repositoryId, serverIdentity],
  );
  const [revision, setRevision] = useState(() => readDataRevision(revisionKey));
  useEffect(() => {
    setRevision(readDataRevision(revisionKey));
    return watchDataRevision(revisionKey, setRevision);
  }, [revisionKey]);
  const namespace = useMemo(
    () => facetNamespace(repositoryScope(basePath, repositoryId, serverIdentity), String(scope), inferenceOn()),
    [basePath, repositoryId, serverIdentity, scope],
  );
  // Read through refs so a new label or candidate function does not start a new store.
  const knownLabelRef = useRef(input.knownLabel);
  knownLabelRef.current = input.knownLabel;
  const candidatesRef = useRef(input.candidates);
  candidatesRef.current = input.candidates;
  const foregroundRef = useRef(input.foreground);
  foregroundRef.current = input.foreground;

  const store = useMemo(
    () =>
      new RepositoryFacetStore({
        execute: (query, signal) => execute(endpoint, query, signal),
        scope,
        maxRows: input.maxRows,
        maxQueryLength: input.maxQueryLength,
        persistence: facetPersistence({
          backend: hasIndexedDb() ? indexedDbFacetBackend() : memoryFacetBackend(),
          baseNamespace: namespace,
          revision,
        }),
        foreground: { idle: () => foregroundRef.current.idle() },
        candidates: () => candidatesRef.current(),
      }),
    [endpoint, execute, scope, input.maxRows, input.maxQueryLength, namespace, revision],
  );
  useEffect(() => () => store.dispose(), [store]);

  const labels = useMemo(
    () =>
      new FacetValueLabels({
        execute: (query, signal) => execute(endpoint, query, signal),
        scope,
        namespace: JSON.stringify([namespace, input.languages, input.labelProperties, [...input.lookupProperties].sort()]),
        languages: input.languages,
        properties: input.labelProperties,
        lookupProperties: input.lookupProperties,
        backend: hasIndexedDb() ? indexedDbFacetBackend<StoredLabel>(LABELS) : memoryFacetBackend<StoredLabel>(),
        foreground: { idle: () => foregroundRef.current.idle() },
        known: (iri) => knownLabelRef.current(iri),
      }),
    [endpoint, execute, scope, namespace, input.languages, input.labelProperties, input.lookupProperties],
  );
  useEffect(() => () => labels.dispose(), [labels]);

  // New values arrive in bursts: the panel recounts at most every PUBLISH_MS.
  const published = useRef(0);
  const subscribe = useCallback(
    (notify: () => void) => {
      let timer: ReturnType<typeof setTimeout> | undefined;
      const ping = () => {
        if (timer) return;
        timer = setTimeout(() => {
          timer = undefined;
          published.current++;
          notify();
        }, PUBLISH_MS);
      };
      const stops = [store.subscribe(ping), labels.subscribe(ping)];
      return () => {
        stops.forEach((stop) => stop());
        if (timer) clearTimeout(timer);
      };
    },
    [store, labels],
  );
  const version = useSyncExternalStore(subscribe, () => published.current, () => 0);

  const { nodeIds, focusIds } = input;
  useEffect(() => {
    if (!nodeIds.length) return;
    const timer = setTimeout(() => {
      store.want(focusIds, "focus");
      store.want(nodeIds, "background");
    }, SETTLE_MS);
    return () => clearTimeout(timer);
  }, [store, nodeIds, focusIds]);

  const refresh = useCallback(() => {
    store.clear();
    labels.clear();
  }, [store, labels]);

  /**
   * Which of the nodes have a selected value (every one of them, for a filter set to "all"), or one inside the range,
   * for the predicate: asked of the repository, one query per value for "all", keeping the nodes every query returns.
   */
  const confirm = useCallback(
    async (predicate: string, ids: readonly string[], match: ExactMatch, signal: AbortSignal) => {
      const matched = new Set<string>();
      for (let offset = 0; offset < ids.length; offset += CONFIRM_BATCH) {
        let batch: string[] | undefined;
        for (const query of exactMatchQueries(ids.slice(offset, offset + CONFIRM_BATCH), predicate, match, scope)) {
          await foregroundRef.current.idle();
          const found = new Set<string>();
          for (const row of (await execute(endpoint, query, signal)).results?.bindings ?? []) {
            if (isSparqlTerm(row.s)) found.add(sparqlNodeId(row.s));
          }
          batch = batch === undefined ? [...found] : batch.filter((id) => found.has(id));
          if (!batch.length) break;
        }
        batch?.forEach((id) => matched.add(id));
      }
      return matched;
    },
    [endpoint, execute, scope],
  );

  const valuesOf = useCallback((id: string) => store.get(id), [store]);
  const labelOf = useCallback((id: string) => labels.label(id), [labels]);
  const wantLabels = useCallback(
    (iris: readonly string[], priority: "shown" | "background") => labels.want(iris, priority),
    [labels],
  );
  // The status and the predicates change with each published version.
  const status = useMemo(() => store.status(), [store, version]);
  const predicates = useMemo(() => store.predicates(), [store, version]);

  return { store, labels, version, status, predicates, refresh, confirm, valuesOf, labelOf, wantLabels };
}
